import { useEffect, useMemo, useState, type ReactNode } from 'react'
import { Link } from 'react-router-dom'
import QRCode from 'qrcode'
import { toast } from 'sonner'
import {
  Activity, BarChart3, BadgeDollarSign, CalendarDays, CheckCircle2, ChevronLeft, ChevronRight,
  ClipboardList, Copy, ExternalLink, Filter, Link2, LockKeyhole, RefreshCw, Search, Send,
  ShieldCheck, SlidersHorizontal, TrendingUp, UserRound, Users, WalletCards, X,
} from 'lucide-react'
import AdminLayout from '../../components/AdminLayout'
import { useAuth } from '../../lib/authContext'
import {
  assignMarketingTeam, getMarketingWorkspace, manageSalesTeam, rotateReferralCode,
  setCommissionRule, updateCommissionStatus, type MarketingCustomer, type MarketingLedgerEntry,
  type MarketingWorkspace,
} from '../../lib/api/marketing'
import { friendlyError } from '../../lib/errors'

type TabKey = 'overview' | 'customers' | 'payments' | 'commissions' | 'referral' | 'performance' | 'activity' | 'team' | 'payouts' | 'policy'
type RangeKey = '7' | '30' | '90' | 'all'
type SortKey = 'businessName' | 'ownerName' | 'paymentStatus' | 'amountRequired' | 'attributedAt'

const money = (value: number) => `${Math.round(value).toLocaleString()} ETB`
const dateText = (value: string | null | undefined) => value ? new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : '—'
const dateTime = (value: string | null | undefined) => value ? new Date(value).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : '—'
const tabs: Array<{ key: TabKey; label: string; icon: typeof Activity }> = [
  { key: 'overview', label: 'Overview', icon: BarChart3 },
  { key: 'customers', label: 'Customers', icon: Users },
  { key: 'payments', label: 'Pending payments', icon: WalletCards },
  { key: 'commissions', label: 'Commissions', icon: BadgeDollarSign },
  { key: 'referral', label: 'Referral center', icon: Link2 },
  { key: 'performance', label: 'Performance', icon: TrendingUp },
  { key: 'activity', label: 'Activity', icon: Activity },
  { key: 'team', label: 'Team management', icon: ShieldCheck },
  { key: 'payouts', label: 'Payouts', icon: WalletCards },
  { key: 'policy', label: 'Marketing policy', icon: ClipboardList },
]

export default function AdminMarketing() {
  const { profile } = useAuth()
  const [workspace, setWorkspace] = useState<MarketingWorkspace | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState('')
  const [tab, setTab] = useState<TabKey>('overview')
  const [range, setRange] = useState<RangeKey>('30')
  const [selectedCustomer, setSelectedCustomer] = useState<MarketingCustomer | null>(null)
  const isSuper = profile?.role === 'super_admin' || profile?.adminRole === 'super_admin'
  const isSales = profile?.adminRole === 'sales_person'
  const isMarketingAdmin = profile?.adminRole === 'marketing_admin'
  const canManage = isSuper || isMarketingAdmin

  async function load(refresh = false) {
    if (!profile) return
    if (refresh) setRefreshing(true); else setLoading(true)
    setError('')
    try { setWorkspace(await getMarketingWorkspace(profile)) } catch (err) { setError(friendlyError(err)) } finally { setLoading(false); setRefreshing(false) }
  }

  useEffect(() => { void load() }, [profile?.id, profile?.adminRole])

  return <AdminLayout>
    <div style={pageHeader}>
      <div><div style={eyebrow}><TrendingUp size={13} /> ABROBIZ MARKETING OPERATIONS</div><h1 style={heading}>{isSales ? 'Sales performance' : isMarketingAdmin ? 'Marketing Admin dashboard' : 'Marketing command center'}</h1><p style={subheading}>{isSales ? 'Build trusted owner relationships, follow payment progress, and track your commission.' : 'A live workspace for attributed customers, full-plan payments, team performance, and commissions.'}</p></div>
      <div style={headerActions}><label style={rangeLabel}><CalendarDays size={14} /><select value={range} onChange={event => setRange(event.target.value as RangeKey)} style={rangeSelect}><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option><option value="all">All time</option></select></label><button type="button" onClick={() => void load(true)} disabled={refreshing} style={secondaryButton}><RefreshCw size={14} style={{ animation: refreshing ? 'marketing-spin .8s linear infinite' : undefined }} /> Refresh</button></div>
    </div>
    {error && <div role="alert" style={errorBox}><X size={16} /> <span>{error}</span><button type="button" onClick={() => void load(true)} style={retryButton}>Try again</button></div>}
    {loading ? <DashboardSkeleton /> : workspace ? <>
      <KpiStrip workspace={workspace} isSales={isSales} />
      <nav aria-label="Marketing dashboard sections" style={tabBar}>{tabs.filter(item => canManage || item.key !== 'team').map(item => { const Icon = item.icon; return <button key={item.key} type="button" onClick={() => setTab(item.key)} style={{ ...tabButton, ...(tab === item.key ? activeTabButton : {}) }}><Icon size={15} />{item.label}</button> })}</nav>
      {tab === 'overview' && <OverviewView workspace={workspace} range={range} isSales={isSales} onCustomer={setSelectedCustomer} />}
      {tab === 'customers' && <CustomersView workspace={workspace} range={range} onCustomer={setSelectedCustomer} />}
      {tab === 'payments' && <PaymentsView workspace={workspace} range={range} onCustomer={setSelectedCustomer} />}
      {tab === 'commissions' && <CommissionsView workspace={workspace} isSuper={isSuper} range={range} onChanged={() => void load(true)} />}
      {tab === 'referral' && <ReferralCenter workspace={workspace} profileId={profile?.id ?? ''} isSales={isSales} range={range} />}
      {tab === 'performance' && <PerformanceView workspace={workspace} range={range} isSales={isSales} />}
      {tab === 'activity' && <ActivityView workspace={workspace} range={range} />}
      {tab === 'team' && canManage && <TeamManagement workspace={workspace} isSuper={isSuper} isMarketingAdmin={isMarketingAdmin} onChanged={() => void load(true)} />}
      {tab === 'payouts' && <PayoutsView workspace={workspace} range={range} isSales={isSales} />}
      {tab === 'policy' && <PolicyView />}
      {selectedCustomer && <CustomerDrawer customer={selectedCustomer} onClose={() => setSelectedCustomer(null)} />}
    </> : null}
    <style>{'@keyframes marketing-spin { to { transform: rotate(360deg); } } @keyframes marketing-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } } @media (max-width: 900px) { .marketing-grid-2 { grid-template-columns: 1fr !important; } .marketing-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; } } @media (max-width: 520px) { .marketing-kpis { grid-template-columns: 1fr !important; } }'}</style>
  </AdminLayout>
}

function KpiStrip({ workspace, isSales }: { workspace: MarketingWorkspace; isSales: boolean }) {
  const cards: Array<[string, number, typeof Users, 'count' | 'money' | 'percent']> = [
    ['Total customers', workspace.summary.customers, Users, 'count'],
    ['Active customers', workspace.summary.activeCustomers, CheckCircle2, 'count'],
    ['Payment pending', workspace.summary.pendingCustomers, WalletCards, 'count'],
    ['Qualifying payments', workspace.summary.qualifyingPayments, BadgeDollarSign, 'money'],
    ['My commission', workspace.summary.myCommission, WalletCards, 'money'],
    ...(!isSales ? [['Team commission', workspace.summary.teamCommission, Users, 'money'] as [string, number, typeof Users, 'money']] : []),
    ['Pending commission', workspace.summary.pendingCommission, SlidersHorizontal, 'money'],
    ['Paid commission', workspace.summary.paidCommission, CheckCircle2, 'money'],
    ['Conversion rate', workspace.summary.conversionRate, TrendingUp, 'percent'],
  ]
  return <div className="marketing-kpis" style={kpiGrid}>{cards.map(([label, value, Icon, kind]) => <div key={label} style={kpiCard}><div style={kpiIcon}><Icon size={17} /></div><div><div style={kpiLabel}>{label}</div><div style={kpiValue}>{kind === 'money' ? money(value) : kind === 'percent' ? `${value}%` : value.toLocaleString()}</div></div></div>)}</div>
}

function OverviewView({ workspace, range, isSales, onCustomer }: { workspace: MarketingWorkspace; range: RangeKey; isSales: boolean; onCustomer: (customer: MarketingCustomer) => void }) {
  const customers = filterByRange(workspace.customers, range)
  const pending = customers.filter(customer => customer.paymentStatus === 'pending' || customer.paymentStatus === 'unpaid').slice(0, 5)
  return <>
    <div className="marketing-grid-2" style={grid2}><section style={panel}><PanelHeader icon={<BarChart3 size={16} />} title="Performance snapshot" subtitle={`${range === 'all' ? 'All recorded activity' : `Activity in the last ${range} days`} · ${customers.length} attributed customers`} /><MetricBars customers={customers} range={range} /></section><section style={panel}><PanelHeader icon={<Activity size={16} />} title="Recent activity" subtitle="Attribution and commission events from the platform" /><ActivityTimeline activities={workspace.activity.slice(0, 6)} /></section></div>
    <div className="marketing-grid-2" style={{ ...grid2, marginTop: 16 }}><section style={panel}><PanelHeader icon={<WalletCards size={16} />} title={isSales ? 'My pending payments' : 'Pending payment center'} subtitle="Payment status is read-only here; approval remains an admin payment workflow." /><PendingRows customers={pending} onCustomer={onCustomer} /></section><section style={panel}><PanelHeader icon={<Link2 size={16} />} title="Referral center" subtitle="Share the system-generated referral link and track conversion." /><ReferralSummary workspace={workspace} range={range} /></section></div>
  </>
}

function CustomersView({ workspace, range, onCustomer }: { workspace: MarketingWorkspace; range: RangeKey; onCustomer: (customer: MarketingCustomer) => void }) {
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('all')
  const [sales, setSales] = useState('all')
  const [sort, setSort] = useState<SortKey>('attributedAt')
  const [ascending, setAscending] = useState(false)
  const [page, setPage] = useState(1)
  const rows = useCustomerRows(workspace.customers, range, search, status, sales, sort, ascending)
  const pageSize = 10
  const visible = rows.slice((page - 1) * pageSize, page * pageSize)
  return <section style={panel}><PanelHeader icon={<Users size={16} />} title="Customers" subtitle="Search attributed owners, inspect payment progress, and open full customer details." /><FilterBar search={search} setSearch={value => { setSearch(value); setPage(1) }} status={status} setStatus={value => { setStatus(value); setPage(1) }} sales={sales} setSales={value => { setSales(value); setPage(1) }} workspace={workspace} /><SortableTableHeader sort={sort} ascending={ascending} setSort={key => { if (key === sort) setAscending(value => !value); else { setSort(key); setAscending(false) } }} /><div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Business / owner</th><th style={th}>Attribution</th><th style={th}>Plan</th><th style={th}>Payment</th><th style={th}>Submitted</th><th style={th}>Action</th></tr></thead><tbody>{visible.map(customer => <CustomerRow key={customer.attributionId} customer={customer} onOpen={() => onCustomer(customer)} />)}</tbody></table>{visible.length === 0 && <EmptyState title="No customers found" body="Try changing the search, status, or date filter." />}</div><Pagination page={page} setPage={setPage} total={rows.length} pageSize={pageSize} /></section>
}

function PaymentsView({ workspace, range, onCustomer }: { workspace: MarketingWorkspace; range: RangeKey; onCustomer: (customer: MarketingCustomer) => void }) {
  const rows = filterByRange(workspace.customers, range).filter(customer => customer.paymentStatus === 'pending' || customer.paymentStatus === 'unpaid')
  return <section style={panel}><PanelHeader icon={<WalletCards size={16} />} title="Pending payment center" subtitle="Real pending and unpaid customers. AbroBiz reminder rules run automatically; payment approval is never editable here." /><div style={notice}><LockKeyhole size={15} /><span>Payment status is read-only in Marketing. Use the Payments workspace for authorized review and approval.</span></div><div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Business / owner</th><th style={th}>Sales Person</th><th style={th}>Plan</th><th style={th}>Required</th><th style={th}>Submitted</th><th style={th}>Remaining</th><th style={th}>Days</th><th style={th}>Last reminder</th><th style={th}>Status</th><th style={th}>Action</th></tr></thead><tbody>{rows.map(customer => <tr key={customer.attributionId}><td style={td}><strong>{customer.businessName}</strong><div style={muted}>{customer.ownerName} · {customer.ownerPlatformId}</div></td><td style={td}>{customer.salesPersonName ?? 'Unassigned'}</td><td style={td}>{customer.planName}</td><td style={td}>{money(customer.amountRequired)}</td><td style={td}>{money(customer.paidAmount)}</td><td style={td}>{money(Math.max(customer.amountRequired - customer.paidAmount, 0))}</td><td style={td}>{customer.daysPending}</td><td style={td}>{dateText(customer.lastReminderAt)}</td><td style={td}><StatusBadge status={customer.paymentStatus} /></td><td style={td}><button type="button" onClick={() => onCustomer(customer)} style={smallAction}>View customer</button></td></tr>)}</tbody></table>{rows.length === 0 && <EmptyState title="No pending payments" body="There are no pending or unpaid attributed customers in this date range." />}</div></section>
}

function CommissionsView({ workspace, isSuper, range, onChanged }: { workspace: MarketingWorkspace; isSuper: boolean; range: RangeKey; onChanged: () => void }) {
  const [status, setStatus] = useState('all')
  const [selected, setSelected] = useState<MarketingLedgerEntry | null>(null)
  const rows = workspace.ledger.filter(entry => entry.entryType === 'original' && (status === 'all' || entry.status === status) && inRange(entry.createdAt, range))
  return <section style={panel}><PanelHeader icon={<BadgeDollarSign size={16} />} title="Commission ledger" subtitle="Generated only after an approved full-plan payment. Reversals remain visible for audit." /><div style={toolbar}><label style={selectLabel}>Status<select value={status} onChange={event => setStatus(event.target.value)} style={filterSelect}><option value="all">All statuses</option>{['pending', 'eligible', 'approved', 'payable', 'paid', 'disputed', 'cancelled'].map(value => <option key={value} value={value}>{value}</option>)}</select></label><span style={pill}>{money(rows.reduce((sum, entry) => sum + entry.amountEtb, 0))} in view</span></div><div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Recipient</th><th style={th}>Rate</th><th style={th}>Amount</th><th style={th}>Status</th><th style={th}>Generated</th><th style={th}>Action</th></tr></thead><tbody>{rows.map(entry => <tr key={entry.id} onClick={() => setSelected(entry)} style={{ cursor: 'pointer' }}><td style={td}>{entry.recipientType.replace('_', ' ')}<div style={muted}>Owner {entry.ownerId.slice(0, 8)}</div></td><td style={td}>{entry.rate}%</td><td style={td}>{money(entry.amountEtb)}</td><td style={td}>{isSuper ? <select value={entry.status} onClick={event => event.stopPropagation()} onChange={event => void updateCommissionStatus(entry.id, event.target.value).then(() => { toast.success('Commission status updated'); onChanged() }).catch(error => toast.error(friendlyError(error)))} style={smallSelect}>{['pending', 'eligible', 'approved', 'payable', 'paid', 'disputed', 'cancelled'].map(value => <option key={value} value={value}>{value}</option>)}</select> : <StatusBadge status={entry.status} />}</td><td style={td}>{dateText(entry.createdAt)}</td><td style={td}><button type="button" onClick={event => { event.stopPropagation(); setSelected(entry) }} style={smallAction}>Details</button></td></tr>)}</tbody></table>{rows.length === 0 && <EmptyState title="No commission entries" body="Commission appears after an approved full plan payment." />}</div>{selected && <CommissionDrawer entry={selected} onClose={() => setSelected(null)} />}</section>
}

function ReferralCenter({ workspace, profileId, isSales, range }: { workspace: MarketingWorkspace; profileId: string; isSales: boolean; range: RangeKey }) {
  const ownedCodes = workspace.referralCodes.filter(code => code.isActive && (isSales ? code.salesPersonId === profileId : workspace.managedSalesIds.includes(code.salesPersonId)))
  const [selectedId, setSelectedId] = useState(ownedCodes[0]?.id ?? '')
  const selected = ownedCodes.find(code => code.id === selectedId) ?? ownedCodes[0]
  const [qrUrl, setQrUrl] = useState('')
  const customers = filterByRange(workspace.customers, range).filter(customer => !selected || customer.referralCode === selected.code || customer.salesPersonId === selected.salesPersonId)
  const link = selected ? `${window.location.origin}/register?ref=${encodeURIComponent(selected.code)}` : ''
  useEffect(() => { setSelectedId(ownedCodes[0]?.id ?? '') }, [ownedCodes.map(item => item.id).join(',')])
  async function showQr() { if (!link) return; setQrUrl(await QRCode.toDataURL(link, { width: 240, margin: 2, color: { dark: '#0A0C10', light: '#FFFFFF' } })) }
  async function copy(value: string, label: string) { await navigator.clipboard?.writeText(value); toast.success(`${label} copied`) }
  async function share() { if (!link) return; if (navigator.share) await navigator.share({ title: 'AbroBiz referral link', text: 'Create your business website with AbroBiz.', url: link }); else await copy(link, 'Referral link') }
  return <div className="marketing-grid-2" style={grid2}><section style={panel}><PanelHeader icon={<Link2 size={16} />} title="Referral center" subtitle="Your referral code is system-generated, unique, and tied to the assigned Sales Person." />{ownedCodes.length > 1 && <label style={selectLabel}>Code<select value={selected?.id ?? ''} onChange={event => { setSelectedId(event.target.value); setQrUrl('') }} style={filterSelect}>{ownedCodes.map(code => <option key={code.id} value={code.id}>{code.code}</option>)}</select></label>}{selected ? <><div style={referralCodeBox}><div><div style={muted}>Referral code</div><strong>{selected.code}</strong></div><button type="button" onClick={() => void copy(selected.code, 'Referral code')} style={iconAction} aria-label="Copy referral code"><Copy size={16} /></button></div><div style={linkBox}><div style={{ minWidth: 0 }}><div style={muted}>Referral link</div><code style={linkText}>{link}</code></div><button type="button" onClick={() => void copy(link, 'Referral link')} style={iconAction} aria-label="Copy referral link"><Copy size={16} /></button></div><div style={buttonRow}><button type="button" onClick={() => void copy(selected.code, 'Referral code')} style={primaryButton}>Copy code</button><button type="button" onClick={() => void copy(link, 'Referral link')} style={secondaryButton}>Copy link</button><button type="button" onClick={() => void showQr()} style={secondaryButton}>Show QR</button><button type="button" onClick={() => void share()} style={secondaryButton}><Send size={14} /> Share</button></div>{qrUrl && <div style={qrBox}><img src={qrUrl} alt="Referral QR code" width={220} height={220} /><button type="button" onClick={() => { const anchor = document.createElement('a'); anchor.href = qrUrl; anchor.download = `${selected.code}-referral-qr.png`; anchor.click() }} style={secondaryButton}>Download QR</button></div>}</> : <EmptyState title="No active referral code" body="A Super Admin must assign a Sales Person before a code is generated." />}</section><section style={panel}><PanelHeader icon={<BarChart3 size={16} />} title="Referral results" subtitle="Calculated from your attributed customer records in this date range." /><ReferralStats customers={customers} commission={workspace.summary.myCommission} /></section></div>
}

function PerformanceView({ workspace, range, isSales }: { workspace: MarketingWorkspace; range: RangeKey; isSales: boolean }) {
  const customers = filterByRange(workspace.customers, range)
  const team = useMemo(() => { const map = new Map<string, { id: string; name: string; referrals: number; paid: number; amount: number; commission: number }>(); for (const customer of customers) { if (!customer.salesPersonId) continue; const current = map.get(customer.salesPersonId) ?? { id: customer.salesPersonId, name: customer.salesPersonName ?? 'Sales Person', referrals: 0, paid: 0, amount: 0, commission: 0 }; current.referrals += 1; current.paid += customer.paymentStatus === 'approved' ? 1 : 0; current.amount += customer.paymentStatus === 'approved' ? customer.paidAmount : 0; map.set(customer.salesPersonId, current) } for (const entry of workspace.ledger) { const current = entry.recipientType === 'sales_person' ? map.get(entry.ownerId) : undefined; if (current) current.commission += entry.amountEtb } return [...map.values()].sort((a, b) => b.paid - a.paid || b.amount - a.amount) }, [customers, workspace.ledger])
  return <><section style={panel}><PanelHeader icon={<TrendingUp size={16} />} title="Performance analytics" subtitle={`${range === 'all' ? 'All time' : `Last ${range} days`} · based on real attribution and approved payment data`} /><MetricBars customers={customers} range={range} detailed /></section><section style={{ ...panel, marginTop: 16 }}><PanelHeader icon={<Users size={16} />} title={isSales ? 'My performance' : 'Sales Person performance'} subtitle={isSales ? 'Your conversion and qualifying payment activity.' : 'Compare attributed referrals and approved full payments across the team.'} /><div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Sales Person</th><th style={th}>Referrals</th><th style={th}>Paid</th><th style={th}>Conversion</th><th style={th}>Qualifying payments</th><th style={th}>Commission</th></tr></thead><tbody>{team.map(row => <tr key={row.id}><td style={td}><strong>{row.name}</strong><div style={muted}>{row.id.slice(0, 8)}</div></td><td style={td}>{row.referrals}</td><td style={td}>{row.paid}</td><td style={td}>{row.referrals ? Math.round(row.paid / row.referrals * 100) : 0}%</td><td style={td}>{money(row.amount)}</td><td style={td}>{money(row.commission)}</td></tr>)}</tbody></table>{team.length === 0 && <EmptyState title="No team performance yet" body="Sales performance appears as referral registrations are recorded." />}</div></section></>
}

function ActivityView({ workspace, range }: { workspace: MarketingWorkspace; range: RangeKey }) { return <section style={panel}><PanelHeader icon={<Activity size={16} />} title="Activity timeline" subtitle="Attribution and commission events visible to your role." /><ActivityTimeline activities={workspace.activity.filter(item => inRange(item.createdAt, range))} full /></section> }
function PayoutsView({ workspace, range, isSales }: { workspace: MarketingWorkspace; range: RangeKey; isSales: boolean }) {
  const customers = filterByRange(workspace.customers, range).filter(customer => customer.paymentId)
  const payouts = workspace.ledger.filter(entry => inRange(entry.createdAt, range) && ['payable', 'paid', 'reversed', 'disputed'].includes(entry.status))
  return <section style={panel}><PanelHeader icon={<WalletCards size={16} />} title={isSales ? 'Payment history' : 'Payouts'} subtitle={isSales ? 'Payment progress for your attributed customers.' : 'Commission entries ready for payout, paid, reversed, or disputed.'} />{isSales ? <div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Customer</th><th style={th}>Plan</th><th style={th}>Required</th><th style={th}>Submitted</th><th style={th}>Status</th><th style={th}>Submitted date</th></tr></thead><tbody>{customers.map(customer => <tr key={customer.paymentId}><td style={td}><strong>{customer.businessName}</strong><div style={muted}>{customer.ownerName}</div></td><td style={td}>{customer.planName}</td><td style={td}>{money(customer.amountRequired)}</td><td style={td}>{money(customer.paidAmount)}</td><td style={td}><StatusBadge status={customer.paymentStatus} /></td><td style={td}>{dateText(customer.paymentCreatedAt)}</td></tr>)}</tbody></table>{customers.length === 0 && <EmptyState title="No payment history" body="Payment submissions from your attributed customers will appear here." />}</div> : <div style={tableWrap}><table className="marketing-page-table" style={table}><thead><tr><th style={th}>Recipient</th><th style={th}>Amount</th><th style={th}>Status</th><th style={th}>Payment</th><th style={th}>Date</th></tr></thead><tbody>{payouts.map(entry => <tr key={entry.id}><td style={td}>{entry.recipientType.replace('_', ' ')}</td><td style={td}>{money(entry.amountEtb)}</td><td style={td}><StatusBadge status={entry.status} /></td><td style={td}>{entry.paymentId.slice(0, 8)}</td><td style={td}>{dateText(entry.createdAt)}</td></tr>)}</tbody></table>{payouts.length === 0 && <EmptyState title="No payout activity" body="Eligible and paid commission entries will appear here." />}</div>}</section>
}
function PolicyView() { return <section style={panel}><PanelHeader icon={<ClipboardList size={16} />} title="Marketing Partner Policy" subtitle="Your marketing access is governed by the accepted AbroBiz policy version." /><div style={policyBox}><LockKeyhole size={19} color="#946F1F" /><div><strong>Keep your partner activity compliant</strong><p style={panelHint}>Commissions are created only after verified full-plan payment. Attribution is locked, and false referrals, misleading promises, duplicate accounts, or unauthorized access may result in suspension.</p><Link to="/marketing-policy" style={primaryLink}>Review the full policy <ExternalLink size={13} /></Link></div></div></section> }
function ReferralSummary({ workspace, range }: { workspace: MarketingWorkspace; range: RangeKey }) { return <><ReferralStats customers={filterByRange(workspace.customers, range)} commission={workspace.summary.myCommission} /><button type="button" onClick={() => toast.info('Open the Referral Center tab to copy your active link.')} style={{ ...primaryLink, border: 0, background: 'transparent', cursor: 'pointer', padding: 0 }}>Open Referral Center →</button></> }
function ReferralStats({ customers, commission }: { customers: MarketingCustomer[]; commission: number }) { const paid = customers.filter(customer => customer.paymentStatus === 'approved').length; const pending = customers.filter(customer => customer.paymentStatus === 'pending' || customer.paymentStatus === 'unpaid').length; return <div style={statsGrid}>{[['Referred', customers.length], ['Registered', customers.length], ['Pending payment', pending], ['Paid', paid], ['Conversion', `${customers.length ? Math.round(paid / customers.length * 100) : 0}%`], ['Commission generated', money(commission)]].map(([label, value]) => <div key={String(label)} style={statTile}><div style={muted}>{label}</div><strong>{value}</strong></div>)}</div> }
function MetricBars({ customers, range, detailed = false }: { customers: MarketingCustomer[]; range: RangeKey; detailed?: boolean }) { const points = buildPoints(customers, range); const max = Math.max(1, ...points.map(point => point.referrals)); return <div><div style={chartLegend}><span><i style={{ ...legendDot, background: '#B98522' }} /> Referrals</span><span><i style={{ ...legendDot, background: '#25A269' }} /> Paid</span></div><div style={chart}>{points.map(point => <div key={point.label} style={chartColumn}><div style={bars}><div title={`${point.referrals} referrals`} style={{ ...bar, height: `${Math.max(point.referrals ? 8 : 2, point.referrals / max * 100)}%`, background: '#D8B66A' }} /><div title={`${point.paid} paid`} style={{ ...bar, height: `${Math.max(point.paid ? 8 : 2, point.paid / max * 100)}%`, background: '#5CB98A' }} /></div><span>{point.label}</span></div>)}</div>{detailed && <div style={chartTotals}><span>{customers.length} referrals</span><span>{customers.filter(customer => customer.paymentStatus === 'approved').length} paid</span><span>{money(customers.reduce((sum, customer) => sum + (customer.paymentStatus === 'approved' ? customer.paidAmount : 0), 0))} qualifying</span></div>}</div> }
function buildPoints(customers: MarketingCustomer[], range: RangeKey) { const days = range === '7' ? 7 : 14; const step = range === '90' || range === 'all' ? 7 : 1; const result = Array.from({ length: days }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (days - index - 1) * step); return { date, label: date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }), referrals: 0, paid: 0 } }); for (const customer of customers) { const timestamp = new Date(customer.attributedAt).getTime(); const point = result.reduce((best, current) => Math.abs(current.date.getTime() - timestamp) < Math.abs(best.date.getTime() - timestamp) ? current : best, result[0]); if (point && timestamp <= Date.now()) { point.referrals += 1; if (customer.paymentStatus === 'approved') point.paid += 1 } } return result }
function PendingRows({ customers, onCustomer }: { customers: MarketingCustomer[]; onCustomer: (customer: MarketingCustomer) => void }) { return customers.length === 0 ? <EmptyState title="Nothing waiting" body="No pending payment follow-up is needed right now." /> : <div>{customers.map(customer => <button type="button" key={customer.attributionId} onClick={() => onCustomer(customer)} style={lineButton}><div><strong>{customer.businessName}</strong><div style={muted}>{customer.ownerName} · {customer.planName}</div></div><div style={{ textAlign: 'right' }}><StatusBadge status={customer.paymentStatus} /><div style={muted}>{customer.daysPending} days</div></div></button>)}</div> }
function ActivityTimeline({ activities, full = false }: { activities: MarketingWorkspace['activity']; full?: boolean }) { return activities.length === 0 ? <EmptyState title="No activity yet" body="New referral and commission events will appear here." /> : <div style={timeline}>{activities.slice(0, full ? 100 : 6).map(activity => <div key={activity.id} style={timelineItem}><span style={{ ...timelineDot, background: activity.kind === 'commission' ? '#25A269' : '#B98522' }} /><div><strong>{activity.title}</strong><div style={muted}>{activity.description}</div><small style={timelineTime}>{dateTime(activity.createdAt)}</small></div></div>)}</div> }
function FilterBar({ search, setSearch, status, setStatus, sales, setSales, workspace }: { search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; sales: string; setSales: (value: string) => void; workspace: MarketingWorkspace }) { const salesPeople = workspace.team.filter(member => member.role === 'sales_person'); return <div style={filterBar}><div style={searchBox}><Search size={15} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search customer, owner, email, platform ID" style={searchInput} /></div><label style={selectLabel}><Filter size={13} /> Status<select value={status} onChange={event => setStatus(event.target.value)} style={filterSelect}><option value="all">All statuses</option><option value="approved">Approved</option><option value="pending">Pending</option><option value="unpaid">Unpaid</option><option value="rejected">Rejected</option></select></label>{salesPeople.length > 0 && <label style={selectLabel}>Sales Person<select value={sales} onChange={event => setSales(event.target.value)} style={filterSelect}><option value="all">All Sales Persons</option>{salesPeople.map(member => <option key={member.id} value={member.id}>{member.name}</option>)}</select></label>}</div> }
function useCustomerRows(customers: MarketingCustomer[], range: RangeKey, search: string, status: string, sales: string, sort: SortKey, ascending: boolean) { return useMemo(() => { const term = search.trim().toLowerCase(); return filterByRange(customers, range).filter(customer => (!term || `${customer.ownerName} ${customer.ownerEmail} ${customer.businessName} ${customer.ownerPlatformId} ${customer.referralCode ?? ''}`.toLowerCase().includes(term)) && (status === 'all' || customer.paymentStatus === status) && (sales === 'all' || customer.salesPersonId === sales)).sort((a, b) => { const left = sort === 'amountRequired' ? a.amountRequired : sort === 'attributedAt' ? new Date(a.attributedAt).getTime() : String(a[sort]).toLowerCase(); const right = sort === 'amountRequired' ? b.amountRequired : sort === 'attributedAt' ? new Date(b.attributedAt).getTime() : String(b[sort]).toLowerCase(); const result = left < right ? -1 : left > right ? 1 : 0; return ascending ? result : -result }) }, [customers, range, search, status, sales, sort, ascending]) }
function filterByRange(customers: MarketingCustomer[], range: RangeKey) { return customers.filter(customer => inRange(customer.attributedAt, range)) }
function inRange(value: string, range: RangeKey) { if (range === 'all') return true; return Date.now() - new Date(value).getTime() <= Number(range) * 86400000 }
function SortableTableHeader({ sort, ascending, setSort }: { sort: SortKey; ascending: boolean; setSort: (key: SortKey) => void }) { return <div style={sortBar}><span>Sort customers by</span>{([['businessName', 'Business'], ['ownerName', 'Owner'], ['paymentStatus', 'Status'], ['amountRequired', 'Plan amount'], ['attributedAt', 'Date']] as Array<[SortKey, string]>).map(([key, label]) => <button type="button" key={key} onClick={() => setSort(key)} style={{ ...sortButton, ...(sort === key ? activeSort : {}) }}>{label}{sort === key ? ascending ? ' ↑' : ' ↓' : ''}</button>)}</div> }
function CustomerRow({ customer, onOpen }: { customer: MarketingCustomer; onOpen: () => void }) { return <tr onClick={onOpen} style={{ cursor: 'pointer' }}><td style={td}><strong>{customer.businessName}</strong><div style={muted}>{customer.ownerName} · {customer.ownerPlatformId}</div><div style={muted}>{customer.ownerEmail}</div></td><td style={td}>{customer.salesPersonName ?? 'Direct / unassigned'}<div style={muted}>{customer.referralCode ?? customer.source}</div></td><td style={td}>{customer.planName}<div style={muted}>{money(customer.amountRequired)}</div></td><td style={td}><StatusBadge status={customer.paymentStatus} /></td><td style={td}>{money(customer.paidAmount)}<div style={muted}>{customer.paymentStatus === 'approved' ? 'approved' : 'submitted'}</div></td><td style={td}><button type="button" onClick={event => { event.stopPropagation(); onOpen() }} style={smallAction}>Details</button></td></tr> }
function Pagination({ page, setPage, total, pageSize }: { page: number; setPage: (value: number) => void; total: number; pageSize: number }) { const pages = Math.max(1, Math.ceil(total / pageSize)); return <div style={pagination}><span>{total === 0 ? '0 records' : `${(page - 1) * pageSize + 1}–${Math.min(page * pageSize, total)} of ${total}`}</span><div style={buttonRow}><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)} style={pageButton}><ChevronLeft size={14} /></button><span style={pageNumber}>{page} / {pages}</span><button type="button" disabled={page >= pages} onClick={() => setPage(page + 1)} style={pageButton}><ChevronRight size={14} /></button></div></div> }

function TeamManagement({ workspace, isSuper, isMarketingAdmin, onChanged }: { workspace: MarketingWorkspace; isSuper: boolean; isMarketingAdmin: boolean; onChanged: () => void }) { const [selectedSales, setSelectedSales] = useState(''); const [selectedAdmin, setSelectedAdmin] = useState(''); const [selectedCode, setSelectedCode] = useState(''); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const sales = workspace.team.filter(member => member.role === 'sales_person'); const admins = workspace.team.filter(member => member.role === 'marketing_admin' || member.role === 'super_admin'); const managedSales = workspace.team.filter(member => member.role === 'sales_person' && workspace.managedSalesIds.includes(member.id)); const codes = new Map(workspace.referralCodes.filter(item => item.isActive).map(item => [item.salesPersonId, item.code])); async function run(action: () => Promise<void>, success: string) { setBusy(true); setMessage(''); try { await action(); setMessage(success); toast.success(success); onChanged() } catch (err) { const messageText = friendlyError(err); setMessage(messageText); toast.error(messageText) } finally { setBusy(false) } } return <section style={panel}><PanelHeader icon={<ShieldCheck size={16} />} title={isSuper ? 'Super Admin controls' : 'My Sales team'} subtitle={isSuper ? 'Manage Marketing Admins, team assignments, system referral codes, and commission rules.' : 'Manage only the Sales Persons assigned to your Marketing Admin account.'} />{isMarketingAdmin && <div style={teamCards}>{managedSales.length === 0 ? <EmptyState title="No Sales Persons assigned" body="Ask a Super Admin to assign a Sales Person to your team." /> : managedSales.map(member => <div key={member.id} style={teamCard}><div style={teamCardTop}><div><strong>{member.name}</strong><div style={muted}>{member.platformId} · {member.email}</div></div><span style={pill}>Sales Person</span></div><div style={codeBox}>{codes.get(member.id) ?? 'Code generating'}{codes.get(member.id) && <button type="button" onClick={() => { void navigator.clipboard?.writeText(`${window.location.origin}/register?ref=${encodeURIComponent(codes.get(member.id)!)}`); toast.success('Referral link copied') }} style={copyButton}><Copy size={13} /> Copy link</button>}</div><button type="button" disabled={busy} onClick={() => void run(() => manageSalesTeam(member.id, 'remove'), 'Sales Person removed from your team.')} style={dangerButton}>Remove from team</button></div>)}</div>}{isSuper && <div style={managementGrid}><div style={managementCard}><strong>Marketing Admin roster</strong>{admins.map(member => <div key={member.id} style={adminRow}><span><strong>{member.name}</strong><small>{member.platformId} · {member.role}</small></span><Link to="/admin/management" style={miniButton}>Manage role</Link></div>)}<Link to="/admin/management" style={primaryLink}>Open full admin management</Link></div><div style={managementCard}><strong>Assign Sales team</strong><select value={selectedSales} onChange={event => setSelectedSales(event.target.value)} style={formInput}><option value="">Select Sales Person</option>{sales.map(member => <option key={member.id} value={member.id}>{member.name} · {member.platformId}</option>)}</select><select value={selectedAdmin} onChange={event => setSelectedAdmin(event.target.value)} style={formInput}><option value="">Select Marketing Admin</option>{admins.map(member => <option key={member.id} value={member.id}>{member.name} · {member.platformId}</option>)}</select><button type="button" disabled={busy || !selectedSales || !selectedAdmin} onClick={() => void run(() => assignMarketingTeam(selectedSales, selectedAdmin), 'Team assignment saved.')} style={primaryButton}>Save assignment</button></div><div style={managementCard}><strong>Rotate system code</strong><select value={selectedCode} onChange={event => setSelectedCode(event.target.value)} style={formInput}><option value="">Select Sales Person</option>{sales.map(member => <option key={member.id} value={member.id}>{member.name}</option>)}</select><button type="button" disabled={busy || !selectedCode} onClick={() => void run(() => rotateReferralCode(selectedCode), 'A new unique referral code was generated.')} style={primaryButton}>Generate unique code</button><div style={muted}>Codes are generated automatically when a Sales Person is assigned.</div></div><CommissionRuleCard workspace={workspace} busy={busy} onSaved={messageText => { setMessage(messageText); onChanged() }} /></div>}{message && <div style={messageBox}>{message}</div>}</section> }
function CommissionRuleCard({ workspace, busy, onSaved }: { workspace: MarketingWorkspace; busy: boolean; onSaved: (message: string) => void }) { const rule = workspace.commissionRule; const [sales, setSales] = useState(String(rule?.salesPersonRate ?? 20)); const [admin, setAdmin] = useState(String(rule?.marketingAdminRate ?? 5)); const [abrobiz, setAbrobiz] = useState(String(rule?.abrobizRate ?? 75)); const total = Number(sales) + Number(admin) + Number(abrobiz); return <div style={managementCard}><strong>Active commission rule</strong><div style={rateGrid}><input type="number" min="0" max="100" value={sales} onChange={event => setSales(event.target.value)} style={formInput} placeholder="Sales %" /><input type="number" min="0" max="100" value={admin} onChange={event => setAdmin(event.target.value)} style={formInput} placeholder="Admin %" /><input type="number" min="0" max="100" value={abrobiz} onChange={event => setAbrobiz(event.target.value)} style={formInput} placeholder="AbroBiz %" /></div><div style={{ ...muted, color: total === 100 ? '#166534' : '#991B1B' }}>Total: {total}% (must equal 100%)</div><button type="button" disabled={busy || total !== 100} onClick={() => setCommissionRule('Standard referral distribution', Number(sales), Number(admin), Number(abrobiz)).then(() => onSaved('Commission rule saved.')).catch(() => onSaved('Could not save commission rule.'))} style={primaryButton}>Save commission rule</button></div> }

function CustomerDrawer({ customer, onClose }: { customer: MarketingCustomer; onClose: () => void }) { return <Drawer title={customer.businessName} onClose={onClose}><div style={drawerHero}><UserRound size={18} /><div><strong>{customer.ownerName}</strong><div style={muted}>{customer.ownerPlatformId} · {customer.ownerEmail}</div></div></div><Detail label="Attribution" value={customer.referralCode ?? customer.source} /><Detail label="Sales Person" value={customer.salesPersonName ?? 'Unassigned'} /><Detail label="Marketing Admin" value={customer.marketingAdminName ?? 'Unassigned'} /><Detail label="Plan" value={`${customer.planName} · ${money(customer.amountRequired)}`} /><Detail label="Payment" value={`${customer.paymentStatus} · ${money(customer.paidAmount)} submitted`} /><Detail label="Remaining" value={money(Math.max(customer.amountRequired - customer.paidAmount, 0))} /><Detail label="Registered" value={dateTime(customer.attributedAt)} /><Detail label="Payment submitted" value={dateTime(customer.paymentCreatedAt)} /><Detail label="Days pending" value={String(customer.daysPending)} /></Drawer> }
function CommissionDrawer({ entry, onClose }: { entry: MarketingLedgerEntry; onClose: () => void }) { return <Drawer title="Commission details" onClose={onClose}><Detail label="Recipient" value={entry.recipientType.replace('_', ' ')} /><Detail label="Amount" value={money(entry.amountEtb)} /><Detail label="Rate" value={`${entry.rate}%`} /><Detail label="Status" value={entry.status} /><Detail label="Payment ID" value={entry.paymentId} /><Detail label="Owner ID" value={entry.ownerId} /><Detail label="Created" value={dateTime(entry.createdAt)} /><div style={policyBox}><BadgeDollarSign size={17} color="#946F1F" /><span>{entry.note || 'Generated from an approved full-plan payment.'}</span></div></Drawer> }
function Drawer({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div role="presentation" style={drawerBackdrop} onClick={onClose}><aside role="dialog" aria-modal="true" aria-label={title} style={drawer} onClick={event => event.stopPropagation()}><div style={drawerHeader}><h2 style={drawerTitle}>{title}</h2><button type="button" onClick={onClose} style={iconAction} aria-label="Close"><X size={18} /></button></div><div style={drawerBody}>{children}</div></aside></div> }
function Detail({ label, value }: { label: string; value: string }) { return <div style={detailRow}><span style={detailLabel}>{label}</span><strong>{value}</strong></div> }
function StatusBadge({ status }: { status: string }) { return <span style={{ ...statusPill, ...statusColor(status) }}>{status}</span> }
function PanelHeader({ icon, title, subtitle }: { icon: ReactNode; title: string; subtitle: string }) { return <div style={panelHeader}><div><h2 style={panelTitle}>{icon}{title}</h2><p style={panelHint}>{subtitle}</p></div></div> }
function EmptyState({ title, body }: { title: string; body: string }) { return <div style={emptyState}><Activity size={18} /><strong>{title}</strong><span>{body}</span></div> }
function DashboardSkeleton() { return <div className="marketing-kpis" style={kpiGrid}>{Array.from({ length: 8 }, (_, index) => <div key={index} style={{ ...kpiCard, minHeight: 75 }}><div style={skeletonCircle} /><div style={{ flex: 1 }}><div style={skeletonLine} /><div style={{ ...skeletonLine, width: '55%', marginTop: 9 }} /></div></div>)}</div> }

function statusColor(status: string): React.CSSProperties { if (status === 'approved' || status === 'paid') return { color: '#166534', background: 'rgba(22,101,52,.1)' }; if (status === 'pending' || status === 'unpaid' || status === 'eligible' || status === 'payable') return { color: '#8A6417', background: 'rgba(212,168,83,.14)' }; return { color: '#991B1B', background: 'rgba(220,38,38,.1)' } }

